beforeExample:
class MyClass {
    boolean myPrimitiveBool = true;
    Boolean myWrapperBool = Boolean.TRUE;

    void testMethod() {
        if (myPrimitiveBool == true) {
            System.out.println("Primitive boolean is true.");
        }
        if (myWrapperBool == true) {
            System.out.println("Wrapper boolean is true.");
        }

        if (myPrimitiveBool == false) {
            System.out.println("Primitive boolean is false.");
        }
        if (myWrapperBool == false) {
            System.out.println("Wrapper boolean is false.");
        }
    }

    boolean methodWithSideEffect() {
        System.out.println("Executing side effect...");
        return true;
    }

    void anotherTestMethod() {
        // These should NOT be transformed due to hasNoSideEffect guard
        if (methodWithSideEffect() == true) {
            System.out.println("Side effect evaluation for true.");
        }
        if (methodWithSideEffect() == false) {
            System.out.println("Side effect evaluation for false.");
        }
    }
}

afterExample:
class MyClass {
    boolean myPrimitiveBool = true;
    Boolean myWrapperBool = Boolean.TRUE;

    void testMethod() {
        if (myPrimitiveBool) {
            System.out.println("Primitive boolean is true.");
        }
        if (myWrapperBool) {
            System.out.println("Wrapper boolean is true.");
        }

        if (!myPrimitiveBool) {
            System.out.println("Primitive boolean is false.");
        }
        if (!myWrapperBool) {
            System.out.println("Wrapper boolean is false.");
        }
    }

    boolean methodWithSideEffect() {
        System.out.println("Executing side effect...");
        return true;
    }

    void anotherTestMethod() {
        // These should NOT be transformed due to hasNoSideEffect guard
        if (methodWithSideEffect() == true) {
            System.out.println("Side effect evaluation for true.");
        }
        if (methodWithSideEffect() == false) {
            System.out.println("Side effect evaluation for false.");
        }
    }
}

negativeExample:
class MyClass {
    String myString = "true";
    int myInt = 1;

    void noMatchMethod() {
        // This is a String comparison, not boolean. Should not match.
        if (myString == "true") {
            System.out.println("String equality check.");
        }
        // This is an int comparison, not boolean. Should not match.
        if (myInt == 1) {
            System.out.println("Integer equality check.");
        }
    }

    boolean methodWithSideEffect() {
        System.out.println("Executing side effect...");
        return true;
    }

    void sideEffectMethod() {
        // This has a side effect, so the rule with hasNoSideEffect() guard
        // should explicitly NOT match this even though it's boolean == true.
        if (methodWithSideEffect() == true) {
            System.out.println("This should NOT be simplified to 'if (methodWithSideEffect())'.");
        }
        // Similarly for '== false'
        if (methodWithSideEffect() == false) {
            System.out.println("This should NOT be simplified to 'if (!methodWithSideEffect())'.");
        }
    }
}
